class Solution {
public:
    int numEquivDominoPairs(vector<vector<int>>& dominoes) {
        int count[10][10] = {};
        int ans = 0;
        for (const auto& d : dominoes) {
            int a = d[0], b = d[1];
            if (a > b) {
                int t = a;
                a = b;
                b = t;
            }
            ans += count[a][b];
            count[a][b]++;
        }
        return ans;
    }
};
